// Widget POSTs: { path, archive_root }
//
// The original folder tree is mirrored underneath the archive root rather than
// dumping everything in one flat folder. Two decades of recipes contain plenty
// of same-named files, and the folder a file sat in is often the only record of
// which product line it belonged to.

const body = $json.body || $json;

const src = String(body.path || '').replace(/^\/+/, '').replace(/\/+$/, '');
const root = String(body.archive_root || 'Squirrely Stash/archive').replace(/^\/+/, '').replace(/\/+$/, '');

if (!src) throw new Error('No source path supplied');
if (!root) throw new Error('No archive root supplied');

// Refuse to archive something already inside the archive: a second click would
// otherwise bury the file one level deeper each time.
if ((src + '/').toLowerCase().startsWith(root.toLowerCase() + '/')) {
  throw new Error('That file is already in the archive');
}

const parts = src.split('/');
const filename = parts.pop();
const srcFolder = parts.join('/');

const destFolder = srcFolder ? root + '/' + srcFolder : root;

// MKCOL will not create intermediate collections, so every level of the
// destination has to be created in order, top down.
const segments = destFolder.split('/');
const levels = [];
let acc = '';
for (const seg of segments) {
  acc = acc ? acc + '/' + seg : seg;
  levels.push(acc);
}

return [{ json: { src, root, filename, srcFolder, destFolder, levels } }];

// One item per folder level, so the Nextcloud node creates them in order.
const plan = $input.first().json;
return plan.levels.map(level => ({ json: { level } }));

// A level that already exists comes back as an error from MKCOL, which is a
// success for our purposes. Errors are swallowed on that node, so nothing to
// check here — just collapse back to the single plan item.
return [$('Plan move').first()];

// WebDAV MOVE overwrites the destination by default, so a name collision
// would silently destroy an older archived file. Suffix instead.

const plan = $('Plan move').first().json;

function decode(p) { try { return decodeURIComponent(p); } catch (e) { return p; } }

const existing = new Set();
for (const item of $input.all()) {
  const p = item.json && item.json.path;
  if (!p) continue;
  existing.add(decode(String(p)).replace(/\/+$/, '').split('/').pop().toLowerCase());
}

const dot = plan.filename.lastIndexOf('.');
const stem = dot > 0 ? plan.filename.slice(0, dot) : plan.filename;
const ext = dot > 0 ? plan.filename.slice(dot) : '';

let finalName = plan.filename;
let n = 2;
while (existing.has(finalName.toLowerCase())) {
  finalName = stem + '-' + n + ext;
  n++;
  if (n > 99) throw new Error('Too many name collisions in the archive folder');
}

return [{ json: {
  src: plan.src,
  dest: plan.destFolder + '/' + finalName,
  renamed: finalName !== plan.filename,
  filename: finalName,
} }];
